  -H "Authorization: Bearer $GITHUB_TOKEN" \
  -H "Accept: application/vnd.github+json" \
  "https://api.github.com/repos/tiendv89/agent-workflow/pulls/142/reviews" \
  -d '{
    "event": "APPROVE",
    "body": "APPROVE — both hook scripts implement the technical design faithfully, all subtasks covered, executable bits set, graceful degradation correct. Only a 🟢 nit (extra header comments in gitnexus-prefetch). Confidence: 0.92.",
    "comments": [
      {
        "path": "technical_skills/rag-enforce/gitnexus-prefetch",
        "line": 3,
        "body": "💡 **Nit** — These three header comments are a welcome addition not present in the technical design spec. No change required."
      }
    ]
  }'
